export default function prepareTelegramTranslation({ body, languageNative, languageTranslate }) {
  const message = body?.message,
    voice = message?.voice;
  if (
    !message ||
    !voice ||
    typeof voice.file_id !== "string" ||
    !voice.file_id ||
    !Number.isSafeInteger(message.chat?.id)
  )
    throw new Error("This workflow requires a Telegram voice message with a chat ID.");
  if (
    typeof languageNative !== "string" ||
    !languageNative.trim() ||
    typeof languageTranslate !== "string" ||
    !languageTranslate.trim() ||
    languageNative.trim().toLowerCase() === languageTranslate.trim().toLowerCase()
  )
    throw new Error("Configure two different translation languages.");
  return {
    chatId: String(message.chat.id),
    fileId: voice.file_id,
    fileRequest: { file_id: voice.file_id },
    languageNative: languageNative.trim(),
    languageTranslate: languageTranslate.trim(),
    voiceMime: typeof voice.mime_type === "string" ? voice.mime_type : "audio/ogg",
  };
}

