import { Buffer } from "node:buffer";
export default async function downloadTelegramVoice(
  { botToken, verified, reply, statusCode, fileId, voiceMime },
  context,
) {
  if (verified !== true || typeof botToken !== "string" || !/^\d+:[A-Za-z0-9_-]+$/.test(botToken))
    throw new Error("Verify the audio Bot Token before downloading.");
  const file = reply?.result,
    path = file?.file_path;
  if (
    statusCode !== 200 ||
    reply?.ok !== true ||
    file?.file_id !== fileId ||
    typeof path !== "string" ||
    !path ||
    path.startsWith("/") ||
    path.split("/").some((x) => !x || x === "." || x === "..") ||
    /[?#\\\x00-\x20]/.test(path)
  )
    throw new Error("Telegram did not confirm a valid downloadable voice file.");
  const ext = path.split(".").at(-1)?.toLowerCase(),
    extensions = {
      oga: "ogg",
      ogg: "ogg",
      opus: "ogg",
      mp3: "mp3",
      m4a: "m4a",
      mp4: "mp4",
      mpeg: "mpeg",
      mpga: "mpga",
      wav: "wav",
      webm: "webm",
      flac: "flac",
    },
    extension = extensions[ext];
  if (!extension) throw new Error("Telegram returned an unsupported voice-file format.");
  try {
    const response = await context.fetch(
      "https://api.telegram.org/file/bot" +
        botToken +
        "/" +
        path.split("/").map(encodeURIComponent).join("/"),
      { method: "GET" },
    );
    if (!response.ok) throw new Error("Download not confirmed.");
    const bytes = new Uint8Array(await response.arrayBuffer());
    if (bytes.length === 0) throw new Error("Empty audio.");
    return {
      file: {
        name: "voice." + extension,
        mimetype:
          typeof voiceMime === "string" && voiceMime.startsWith("audio/")
            ? voiceMime
            : "application/octet-stream",
        content_base64: Buffer.from(bytes).toString("base64"),
      },
      audioBytes: bytes.length,
    };
  } catch {
    throw new Error("Telegram voice download failed; no partial audio is returned.");
  }
}

