export default function telegramTranslationPrompt({
  transcription,
  languageNative,
  languageTranslate,
}) {
  const text = transcription?.text;
  if (typeof text !== "string" || !text.trim())
    throw new Error("Transcription did not return nonempty text.");
  if (typeof languageNative !== "string" || typeof languageTranslate !== "string")
    throw new Error("Missing language configuration.");
  return {
    transcription: text,
    prompt:
      "Detect the language of the text that follows. \n- If it is " +
      languageNative +
      " translate to " +
      languageTranslate +
      ". \n- If it is in " +
      languageTranslate +
      " translate to " +
      languageNative +
      " . \n- In the output just provide the translation and do not explain it. Just provide the translation without anything else.\n\nText:\n " +
      text +
      "\n",
  };
}

