export default function confirmTelegramTranslationText({ message, chatId }) {
  if (
    !Number.isSafeInteger(message?.messageId) ||
    message.messageId < 1 ||
    String(message.chat?.id) !== chatId
  )
    throw new Error("Telegram text reply was not confirmed; inspect the chat before replay.");
  return { textMessage: message };
}

