import { Buffer } from "node:buffer";
export default async function sendTelegramTranslatedAudio(
  { botToken, verified, chatId, contentBase64, contentType },
  context,
) {
  if (
    verified !== true ||
    typeof botToken !== "string" ||
    !/^\d+:[A-Za-z0-9_-]+$/.test(botToken) ||
    typeof chatId !== "string" ||
    !/^\-?\d+$/.test(chatId)
  )
    throw new Error("Verify the Telegram audio bot and chat before sending.");
  if (
    typeof contentBase64 !== "string" ||
    !contentBase64 ||
    contentBase64.length % 4 !== 0 ||
    !/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(contentBase64)
  )
    throw new Error("Speech returned invalid audio encoding.");
  if (
    typeof contentType !== "string" ||
    !["audio/mpeg", "audio/mp3", "application/octet-stream"].includes(
      contentType.split(";")[0].trim().toLowerCase(),
    )
  )
    throw new Error("Speech did not return MP3 audio.");
  const audioBuffer = Buffer.from(contentBase64, "base64"),
    audio = new Uint8Array(audioBuffer);
  if (!audio.length || audioBuffer.toString("base64") !== contentBase64)
    throw new Error("Speech returned incomplete audio encoding.");
  let index = 0,
    boundary;
  do {
    boundary = "oomol-telegram-audio-" + index++;
  } while (audioBuffer.includes(Buffer.from(boundary)));
  const head = new TextEncoder().encode(
      "--" +
        boundary +
        '\r\nContent-Disposition: form-data; name="chat_id"\r\n\r\n' +
        chatId +
        "\r\n--" +
        boundary +
        '\r\nContent-Disposition: form-data; name="audio"; filename="translation.mp3"\r\nContent-Type: audio/mpeg\r\n\r\n',
    ),
    tail = new TextEncoder().encode("\r\n--" + boundary + "--\r\n"),
    body = new Uint8Array(head.length + audio.length + tail.length);
  body.set(head);
  body.set(audio, head.length);
  body.set(tail, head.length + audio.length);
  try {
    const response = await context.fetch("https://api.telegram.org/bot" + botToken + "/sendAudio", {
      method: "POST",
      headers: { "content-type": "multipart/form-data; boundary=" + boundary },
      body,
    });
    if (!response.ok) throw new Error("Send not confirmed.");
    const reply = await response.json(),
      message = reply?.result;
    if (
      reply?.ok !== true ||
      !Number.isSafeInteger(message?.message_id) ||
      message.message_id < 1 ||
      String(message.chat?.id) !== chatId ||
      typeof message.audio?.file_id !== "string" ||
      !message.audio.file_id
    )
      throw new Error("Invalid audio receipt.");
    return { audioMessage: message, audioBytes: audio.length };
  } catch {
    throw new Error("Telegram audio reply was not confirmed; inspect the chat before replay.");
  }
}
